"use client"

/** Clean-room proposal dialog frame. No theme of its own. */

import * as React from "react"
import { Dialog as DialogPrimitive } from "radix-ui"
import { motion, useReducedMotion } from "motion/react"
import { XIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogDescription,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
} from "@/components/ui/dialog"
import { cn } from "@/lib/utils"

export type ProposalMotionDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  title: string
  description?: string
  children: React.ReactNode
  className?: string
  closeLabel?: string
}

export function ProposalMotionDialog({
  open,
  onOpenChange,
  title,
  description,
  children,
  className,
  closeLabel = "Close",
}: ProposalMotionDialogProps) {
  const reduced = !!useReducedMotion()
  const titleId = React.useId()
  const descriptionId = React.useId()

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogPortal>
        <DialogOverlay className="duration-200" />
        <DialogPrimitive.Content
          data-slot="proposal-dialog"
          data-motion={reduced ? "reduced" : "full"}
          aria-labelledby={titleId}
          aria-describedby={description ? descriptionId : undefined}
          className={cn(
            "fixed top-1/2 left-1/2 z-50 w-[min(100%-2rem,36rem)] max-h-[min(100dvh-2rem,40rem)] -translate-x-1/2 -translate-y-1/2 overflow-y-auto rounded-xl bg-popover p-4 text-sm text-popover-foreground shadow-lg ring-1 ring-foreground/10 outline-none",
            className,
          )}
        >
          <motion.div
            className="grid gap-4"
            initial={reduced ? false : { opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: reduced ? 0 : 0.2 }}
          >
            <div className="flex items-start justify-between gap-3 pe-8">
              <div className="min-w-0">
                <DialogTitle id={titleId} className="text-base">
                  {title}
                </DialogTitle>
                {description ? (
                  <DialogDescription id={descriptionId} className="mt-1">
                    {description}
                  </DialogDescription>
                ) : null}
              </div>
            </div>
            <DialogPrimitive.Close asChild>
              <Button type="button" variant="ghost" size="icon-sm" className="absolute top-2 right-2" aria-label={closeLabel}>
                <XIcon />
              </Button>
            </DialogPrimitive.Close>
            {children}
          </motion.div>
        </DialogPrimitive.Content>
      </DialogPortal>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import { FileUp, RotateCcw, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"

export type DropzoneItem = {
  id: string
  name: string
  size: number
  type: string
  progress: number
  status: "uploading" | "done" | "error"
  error?: string
  retryable?: boolean
}

export type MagneticDropzoneProps = {
  accept?: string
  maxSize?: number
  maxFiles?: number
  items?: readonly DropzoneItem[]
  onItemsChange?: (items: DropzoneItem[]) => void
  onFiles?: (files: File[]) => void
  /** Uploads each accepted file. Progress is 0–100. Reject to mark the row failed. Removing the row aborts the signal. */
  onUpload?: (file: File, options: { onProgress: (percent: number) => void; signal: AbortSignal }) => Promise<void>
  simulateProgress?: boolean
  label?: string
  hint?: string
  removeLabel?: string
  retryLabel?: string
  tooLargeLabel?: string
  typeLabel?: string
  className?: string
}

function formatBytes(size: number) {
  if (size < 1024) return `${size} B`
  if (size < 1024 * 1024) return `${Math.round(size / 1024)} KB`
  return `${(size / (1024 * 1024)).toFixed(1)} MB`
}

function matchesAccept(file: File, accept: string | undefined) {
  if (!accept) return true
  const rules = accept.split(",").map((rule) => rule.trim().toLowerCase()).filter(Boolean)
  const name = file.name.toLowerCase()
  const type = file.type.toLowerCase()
  return rules.some((rule) => {
    if (rule.startsWith(".")) return name.endsWith(rule)
    if (rule.endsWith("/*")) return type.startsWith(rule.slice(0, -1))
    return type === rule
  })
}

export function MagneticDropzone({
  accept,
  maxSize = 8 * 1024 * 1024,
  maxFiles = 8,
  items,
  onItemsChange,
  onFiles,
  onUpload,
  simulateProgress = false,
  label = "Drop files here",
  hint = "or choose them from your computer",
  removeLabel = "Remove",
  retryLabel = "Retry",
  tooLargeLabel = "File is too large",
  typeLabel = "File type is not allowed",
  className,
}: MagneticDropzoneProps) {
  const [local, setLocal] = React.useState<DropzoneItem[]>([])
  const [over, setOver] = React.useState(false)
  const [pull, setPull] = React.useState({ x: 0, y: 0 })
  const inputRef = React.useRef<HTMLInputElement>(null)
  const depth = React.useRef(0)
  const list = items ?? local
  const listRef = React.useRef(list)
  const filesRef = React.useRef(new Map<string, File>())
  const uploadsRef = React.useRef(new Map<string, AbortController>())

  React.useEffect(() => {
    listRef.current = list
  }, [list])

  function commit(next: DropzoneItem[]) {
    listRef.current = next
    if (items === undefined) setLocal(next)
    onItemsChange?.(next)
  }

  function patchItem(id: string, update: (item: DropzoneItem) => DropzoneItem) {
    commit(listRef.current.map((item) => (item.id === id ? update(item) : item)))
  }

  function startUpload(id: string, file: File) {
    if (!onUpload) return
    uploadsRef.current.get(id)?.abort()
    const controller = new AbortController()
    uploadsRef.current.set(id, controller)
    patchItem(id, (item) => ({ ...item, status: "uploading", progress: 0, error: undefined }))
    void onUpload(file, {
      signal: controller.signal,
      onProgress: (percent) => {
        patchItem(id, (item) => ({ ...item, progress: Math.max(0, Math.min(100, percent)) }))
      },
    })
      .then(() => {
        if (controller.signal.aborted) return
        patchItem(id, (item) => ({ ...item, status: "done", progress: 100, error: undefined }))
      })
      .catch((error: unknown) => {
        if (controller.signal.aborted) return
        const message = error instanceof Error && error.message ? error.message : "Upload failed"
        patchItem(id, (item) => ({ ...item, status: "error", error: message }))
      })
  }

  function ingest(files: File[]) {
    const room = Math.max(0, maxFiles - list.length)
    const accepted: File[] = []
    const next = list.slice()
    for (const file of files.slice(0, room)) {
      const id = `${file.name}-${file.size}-${file.lastModified}-${next.length}`
      if (!matchesAccept(file, accept)) {
        next.push({ id, name: file.name, size: file.size, type: file.type, progress: 0, status: "error", error: typeLabel })
        continue
      }
      if (file.size > maxSize) {
        next.push({ id, name: file.name, size: file.size, type: file.type, progress: 0, status: "error", error: tooLargeLabel })
        continue
      }
      accepted.push(file)
      filesRef.current.set(id, file)
      next.push({
        id,
        name: file.name,
        size: file.size,
        type: file.type,
        progress: onUpload || simulateProgress ? 8 : 100,
        status: onUpload || simulateProgress ? "uploading" : "done",
        retryable: Boolean(onUpload),
      })
    }
    commit(next)
    if (accepted.length) onFiles?.(accepted)
    if (onUpload) {
      for (const file of accepted) {
        const match = next.find((item) => filesRef.current.get(item.id) === file && item.status === "uploading")
        if (match) startUpload(match.id, file)
      }
    }
  }

  React.useEffect(() => {
    if (!simulateProgress || onUpload) return
    const id = window.setInterval(() => {
      const current = listRef.current
      if (!current.some((item) => item.status === "uploading")) return
      const next = current.map((item) => {
        if (item.status !== "uploading") return item
        const progress = Math.min(100, item.progress + 14)
        return {
          ...item,
          progress,
          status: progress >= 100 ? "done" : "uploading",
        } as DropzoneItem
      })
      if (items === undefined) setLocal(next)
      onItemsChange?.(next)
    }, 280)
    return () => window.clearInterval(id)
  }, [items, onItemsChange, onUpload, simulateProgress])

  function onPointerMove(event: React.PointerEvent<HTMLDivElement>) {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const rect = event.currentTarget.getBoundingClientRect()
    const x = (event.clientX - rect.left) / rect.width - 0.5
    const y = (event.clientY - rect.top) / rect.height - 0.5
    const strength = over ? 18 : 10
    setPull({ x: x * strength, y: y * strength })
  }

  return (
    <div data-slot="magnetic-dropzone" className={cn("flex flex-col gap-3", className)}>
      <div
        onPointerMove={onPointerMove}
        onPointerLeave={() => setPull({ x: 0, y: 0 })}
        onDragEnter={(event) => {
          event.preventDefault()
          depth.current += 1
          setOver(true)
        }}
        onDragOver={(event) => {
          event.preventDefault()
          setOver(true)
        }}
        onDragLeave={() => {
          depth.current = Math.max(0, depth.current - 1)
          if (depth.current === 0) setOver(false)
        }}
        onDrop={(event) => {
          event.preventDefault()
          depth.current = 0
          setOver(false)
          ingest(Array.from(event.dataTransfer.files))
        }}
        className="rounded-xl"
      >
        <button
          type="button"
          onClick={() => inputRef.current?.click()}
          data-over={over ? "true" : "false"}
          className={cn(
            "flex w-full flex-col items-center gap-2 rounded-xl border border-dashed border-border bg-card px-4 py-8 text-center transition-transform duration-150 motion-reduce:transition-none focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            over && "scale-[1.02] border-primary bg-primary/5",
          )}
          style={{ transform: `translate(${pull.x}px, ${pull.y}px)${over ? " scale(1.02)" : ""}` }}
        >
          <FileUp className="size-5 text-muted-foreground" />
          <span className="text-sm font-medium">{label}</span>
          <span className="text-xs text-muted-foreground">{hint}</span>
        </button>
        <input
          ref={inputRef}
          type="file"
          accept={accept}
          multiple
          className="sr-only"
          onChange={(event) => {
            ingest(Array.from(event.target.files ?? []))
            event.target.value = ""
          }}
        />
      </div>
      {list.length > 0 ? (
        <ul className="flex flex-col gap-2">
          {list.map((item) => (
            <li key={item.id} data-status={item.status} className="rounded-lg border border-border px-3 py-2">
              <div className="flex items-center gap-2">
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm">{item.name}</p>
                  <p className="text-[11px] text-muted-foreground tabular-nums">
                    {item.error ?? formatBytes(item.size)}
                  </p>
                </div>
                {item.status === "error" && item.retryable ? (
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon-xs"
                    aria-label={`${retryLabel} ${item.name}`}
                    onClick={() => {
                      const file = filesRef.current.get(item.id)
                      if (file) startUpload(item.id, file)
                    }}
                  >
                    <RotateCcw />
                  </Button>
                ) : null}
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-xs"
                  aria-label={`${removeLabel} ${item.name}`}
                  onClick={() => {
                    uploadsRef.current.get(item.id)?.abort()
                    uploadsRef.current.delete(item.id)
                    filesRef.current.delete(item.id)
                    commit(list.filter((entry) => entry.id !== item.id))
                  }}
                >
                  <X />
                </Button>
              </div>
              {item.status !== "error" ? (
                <div
                  className="mt-2 h-1 overflow-hidden rounded-full bg-muted"
                  role="progressbar"
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-valuenow={item.progress}
                  aria-label={item.name}
                >
                  <div
                    className={cn("h-full rounded-full", item.status === "done" ? "bg-primary" : "bg-foreground/70")}
                    style={{ width: `${item.progress}%` }}
                  />
                </div>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  )
}

"use client"

/** Adapted from Arc UI (MIT). */

import * as React from "react"
import { LayoutGroup, motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"

export type Segment = {
  value: string
  label: string
  accessory?: React.ReactNode
  /** Drawn before the label. With `iconsOnly`, the label stays available to assistive tech. */
  icon?: React.ReactNode
}

export type SegmentedControlClassNames = {
  root?: string
  track?: string
  option?: string
  selection?: string
  label?: string
}

export type SegmentedControlProps = {
  options: Segment[]
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  label?: string
  onOptionIntent?: (value: string) => void
  /** Hides each label visually and keeps it in the accessible name. */
  iconsOnly?: boolean
  className?: string
  classNames?: SegmentedControlClassNames
}

export function SegmentedControl({
  options,
  value,
  defaultValue,
  onValueChange,
  label,
  onOptionIntent,
  iconsOnly = false,
  className,
  classNames,
}: SegmentedControlProps) {
  const id = React.useId()
  const reduced = useReducedMotion()
  const track = React.useRef<HTMLDivElement>(null)
  const [internal, setInternal] = React.useState(defaultValue ?? options[0]?.value ?? "")
  const selected = value ?? internal

  React.useLayoutEffect(() => {
    const node = track.current
    if (!node) return
    const edges = () => {
      const rest = node.scrollWidth - node.clientWidth - node.scrollLeft
      node.toggleAttribute("data-fade-start", node.scrollLeft > 1)
      node.toggleAttribute("data-fade-end", rest > 1)
    }
    edges()
    node.addEventListener("scroll", edges, { passive: true })
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(edges)
    observer?.observe(node)
    return () => {
      node.removeEventListener("scroll", edges)
      observer?.disconnect()
    }
  }, [options.length])

  const first = React.useRef(true)
  React.useEffect(() => {
    const node = track.current
    const button = node?.querySelector<HTMLElement>('[aria-pressed="true"]')
    if (!node || !button || node.scrollWidth <= node.clientWidth) {
      first.current = false
      return
    }
    const room = 20
    const start = button.offsetLeft - room
    const end = button.offsetLeft + button.offsetWidth + room - node.clientWidth
    const left = node.scrollLeft > start ? start : node.scrollLeft < end ? end : node.scrollLeft
    if (left !== node.scrollLeft) node.scrollTo({ left: Math.max(0, left), behavior: first.current || reduced ? "auto" : "smooth" })
    first.current = false
  }, [selected, reduced])

  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === selected))

  function change(next: string) {
    if (value === undefined) setInternal(next)
    onValueChange?.(next)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const last = options.length - 1
    const target =
      event.key === "ArrowRight" || event.key === "ArrowDown"
        ? selectedIndex === last
          ? 0
          : selectedIndex + 1
        : event.key === "ArrowLeft" || event.key === "ArrowUp"
          ? selectedIndex === 0
            ? last
            : selectedIndex - 1
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? last
              : -1
    if (target < 0 || !options[target]) return
    event.preventDefault()
    change(options[target].value)
    track.current?.querySelector<HTMLElement>(`[data-value="${CSS.escape(options[target].value)}"]`)?.focus({ preventScroll: true })
  }

  return (
    <div
      data-slot="segmented-control"
      className={cn("inline-flex min-w-0 max-w-full shrink", className, classNames?.root)}
      role="group"
      aria-label={label}
    >
      <LayoutGroup id={id}>
        <motion.div
          ref={track}
          layoutScroll
          data-slot="segmented-control-track"
          className={cn(
            "flex min-w-0 gap-0.5 overflow-x-auto rounded-lg bg-muted p-0.5 [scrollbar-width:none]",
            classNames?.track,
          )}
        >
          {options.map((option, index) => {
            const pressed = selected === option.value
            return (
              <button
                key={option.value}
                id={`${id}-${option.value}`}
                type="button"
                data-slot="segmented-control-option"
                data-value={option.value}
                className={cn(
                  "relative min-h-8 shrink-0 cursor-pointer rounded-md border-0 bg-transparent px-3 text-sm font-medium whitespace-nowrap text-muted-foreground transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none aria-pressed:text-foreground",
                  classNames?.option,
                )}
                aria-pressed={pressed}
                tabIndex={index === selectedIndex ? 0 : -1}
                onClick={() => change(option.value)}
                onKeyDown={onKeyDown}
                onPointerEnter={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
                onFocus={onOptionIntent ? () => onOptionIntent(option.value) : undefined}
              >
                {pressed ? (
                  <motion.span
                    data-slot="segmented-control-selection"
                    className={cn("absolute inset-0 z-0 rounded-md border border-border bg-background shadow-sm", classNames?.selection)}
                    layoutId="selection"
                    layoutDependency={selected}
                    transition={reduced ? { duration: 0 } : motionPresets.spring.morph}
                    aria-hidden="true"
                  />
                ) : null}
                <span data-slot="segmented-control-label" className={cn("relative z-10 inline-flex items-center gap-1.5", classNames?.label)}>
                  {option.icon}
                  {iconsOnly ? <span className="sr-only">{option.label}</span> : option.label}
                  {option.accessory}
                </span>
              </button>
            )
          })}
        </motion.div>
      </LayoutGroup>
    </div>
  )
}

/**
 * Timing presets for pieces adapted from Arc UI (MIT).
 * Durations and springs only. No colors, fonts, or theme tokens.
 */
export const motionPresets = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    exit: 0.18,
    standard: 0.24,
    considered: 0.48,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1] as const,
    exit: [0.7, 0, 0.84, 0] as const,
    standard: [0.22, 1, 0.36, 1] as const,
    inOut: [0.65, 0, 0.35, 1] as const,
  },
  spring: {
    responsive: { type: "spring" as const, stiffness: 520, damping: 38 },
    gentle: { type: "spring" as const, stiffness: 340, damping: 34 },
    snappy: { type: "spring" as const, visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring" as const, visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring" as const, visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { char: 0.016, word: 0.04, line: 0.08, item: 0.035 },
  blur: { subtle: 2, soft: 4, text: 8 },
}
